const j = $json || {};
const b = $binary || {};
const backendUrl = String(j.backendUrl || 'https://admin.littleherolabs.com').replace(/\/$/, '');
const manifestUrl =
  j.manifest_3_url ||
  j.manifest3Url ||
  j.manifestUrl ||
  (j.manifest3Key ? backendUrl + '/api/manifests/' + j.manifest3Key : null) ||
  (j.manifestKey ? backendUrl + '/api/manifests/' + j.manifestKey : null);

if (!j.orderId) {
  throw new Error('Complete Workflow Job (3): missing orderId');
}

if (!manifestUrl) {
  throw new Error('Complete Workflow Job (3): missing manifestUrl');
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: backendUrl + '/api/webhooks/workflow-3-complete',
  headers: {
    Authorization: 'Bearer e41d510ce6ed6e9c7f602fea860f2591cc7ec75fe63e448336a97c4b73898646',
    'Content-Type': 'application/json',
  },
  body: {
    orderId: j.orderId,
    manifestUrl,
  },
  json: true,
  timeout: 90000,
});

return {
  json: {
    ...j,
    manifest3Url: j.manifest3Url || j.manifest_3_url || manifestUrl,
    manifest_3_url: j.manifest_3_url || j.manifest3Url || manifestUrl,
    workflowJobCompletion: response && typeof response === 'object' ? response : null,
  },
  binary: b,
};

/**
 * Fetch and Merge Review Stages (3)
 * Fetches current order from Supabase and merges existing review_stages
 * with new postPdf data to preserve preBria and postBria stages.
 * 
 * ISSUE: Supabase's resolution=merge-duplicates does NOT deep-merge JSONB.
 * It replaces the entire review_stages object, losing preBria and postBria.
 * 
 * SOLUTION: Fetch existing review_stages, merge manually, then upsert.
 */
// S3 upload node drops JSON data, so fetch from previous node (Prep Manifest Upload)
let input = {};
let prepData = {};

try {
  // Try to get data from Prep Manifest Upload node (previous node)
  const prepItems = $items('Prep Manifest Upload (3)', 0, $runIndex);
  if (Array.isArray(prepItems) && prepItems.length > 0) {
    prepData = prepItems[0].json || {};
  } else if (prepItems?.json) {
    prepData = prepItems.json;
  }
} catch (error) {
  console.warn('⚠️ Could not fetch from Prep Manifest Upload node:', error.message);
}

// Also check current input (S3 node might have some data)
const currentInput = $input.first().json || {};

// Merge: prefer prepData, fallback to currentInput
input = { ...currentInput, ...prepData };

// Per-book orderId (sibling support): prefer orderId column for query
const perBookId = input.orderId || input.manifest?.order?.orderId || null;
const fallbackId = input.amazonOrderId || input.manifest?.order?.amazonOrderId || null;

// If still not found, try to extract from manifestKey
let extractedOrderId = null;
if (!perBookId && !fallbackId && input.manifestKey) {
  const manifestKeyStr = String(input.manifestKey).trim();
  const match = manifestKeyStr.match(/orders\/([^\/]+)\//);
  if (match && match[1]) {
    extractedOrderId = match[1];
    console.log(`✓ Extracted orderId from manifestKey: ${extractedOrderId}`);
  }
}

const queryColumn = perBookId ? 'orderId' : 'amazon_order_id';
const queryId = perBookId || fallbackId || extractedOrderId;

if (!queryId) {
  throw new Error('orderId/amazonOrderId is required. Checked: input.orderId, input.amazonOrderId, input.manifest.order, input.manifestKey. Available keys: ' + JSON.stringify(Object.keys(input || {})));
}

// Supabase config
const supabaseUrl = 'https://mdnthwpcnphjnnblbvxk.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs';

// Fetch current order from Supabase (query by orderId when per-book, else amazon_order_id)
let existingReviewStages = {};

try {
  const fetchResponse = await this.helpers.request({
    method: 'GET',
    uri: `${supabaseUrl}/rest/v1/orders?${queryColumn}=eq.${encodeURIComponent(queryId)}&select=review_stages`,
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    json: true
  });

  // Supabase REST API returns an array
  const orders = Array.isArray(fetchResponse) ? fetchResponse : (fetchResponse ? [fetchResponse] : []);

  if (orders.length > 0) {
    let reviewStages = orders[0].review_stages;

    // Handle case where review_stages might be a JSON string (PostgreSQL JSONB)
    if (typeof reviewStages === 'string') {
      try {
        reviewStages = JSON.parse(reviewStages);
      } catch (parseError) {
        console.warn('⚠️ Failed to parse review_stages JSON string:', parseError.message);
        reviewStages = null;
      }
    }

    // Only use if it's a valid object (not null, not empty string)
    if (reviewStages && typeof reviewStages === 'object' && Object.keys(reviewStages).length > 0) {
      existingReviewStages = reviewStages;
      console.log('✓ Fetched existing review_stages:', JSON.stringify(existingReviewStages, null, 2));
      console.log('✓ Has preBria?', !!existingReviewStages.preBria);
      console.log('✓ Has postBria?', !!existingReviewStages.postBria);
      console.log('✓ Has postPdf?', !!existingReviewStages.postPdf);
    } else {
      console.log('⚠️ review_stages is null or empty, starting fresh');
    }
  } else {
    console.log('⚠️ No order found in Supabase for:', queryColumn, queryId);
  }
} catch (error) {
  console.error('❌ Failed to fetch existing review_stages:', error.message);
  console.error('Error details:', JSON.stringify(error, null, 2));
  // Continue with empty review_stages - better than losing data
}

// Build new postPdf data
// NOTE: Review is ALWAYS needed after W3, so status is always 'in-review'
// needsHumanReview is not set (no auto-flagging in W3)
const newPostPdf = {
  status: 'in-review',  // ALWAYS 'in-review' (review always needed after W3)
  // needsHumanReview: false,  // Optional - not set since no auto-flagging in W3
};

// Merge: preserve existing preBria and postBria, update postPdf
const mergedReviewStages = {
  ...existingReviewStages,  // Preserve preBria, postBria, and any other stages
  postPdf: newPostPdf       // Update/overwrite postPdf
};

console.log('✓ Merged review_stages:', JSON.stringify(mergedReviewStages, null, 2));
console.log('✓ Merged has preBria?', !!mergedReviewStages.preBria);
console.log('✓ Merged has postBria?', !!mergedReviewStages.postBria);
console.log('✓ Merged has postPdf?', !!mergedReviewStages.postPdf);

// Construct manifest URL from manifestKey (use per-book orderId for path)
// manifestKey format: book-mvp-simple-adventure/orders/{orderId}/manifests/3-manifest.json
const manifestKey = input.manifestKey || `book-mvp-simple-adventure/orders/${perBookId || queryId}/manifests/3-manifest.json`;
const backendUrl = input.backendUrl || 'https://admin.littleherolabs.com';
const manifestUrl = `${backendUrl}/api/manifests/${manifestKey}`;

// Pass through all input data + merged review_stages + manifestUrl
// Preserve all fields from prepData (manifest, orderId, etc.)
return [{
  json: {
    ...prepData,  // Preserve all data from Prep Manifest Upload
    ...input,     // Merge with current input
    // Add merged review_stages for Supabase upsert
    mergedReviewStages,
    // Add manifest URL for Supabase
    manifestUrl,
    manifestKey,
    orderId: perBookId || queryId,
    amazonOrderId: fallbackId || perBookId || queryId
  }
}];

