  --text-inset-bottom: var(--text-inset-y);
  --text-inset-left: var(--text-inset-x);
  --text-inset-right: var(--text-inset-x);

  /* Text block alignment inside its padded area */
  --text-vertical-align: center;   /* start | center | end */
}

/* Fixed canvas — no scaling */
html, body { margin:0; padding:0; width:2625px; height:2625px; overflow:hidden; background:#111; }
* { box-sizing:border-box; }
.book-page{
  position:relative; width:2625px; height:2625px; overflow:hidden; display:block; background:#000;
