/* The PNG overlay fills the box area */
.text-box__overlay{
  position:absolute; inset:0;
  width:100%; height:100%;
  object-fit: contain; /* no crop */
  display:block; pointer-events:none; z-index:0;
}

/* Text inside the overlay with PER-SIDE insets */
.text-content{
  position:absolute;
  top:    var(--tb-inset-top,    var(--text-inset-top));
