  font-family:var(--book-font);
  font-size:50px; line-height:1.35; letter-spacing:1px; color:#312116;

  white-space:pre-line; text-wrap:balance; overflow-wrap:break-word; word-break:normal;
  text-rendering:optimizeLegibility; -webkit-font-smoothing:antialiased;
