  <div class="book-page" id="page-${TARGET_PAGE}">
    <div class="page-bg" style="background-image:url('${bgUrl}')"></div>
    ${overlayUrl ? `<div class="page-overlay" style="background-image:url('${overlayUrl}')"></div>` : ''}
    <!-- Per-page overrides? Add style="" on the next div with any of:
         --tb-x, --tb-center, --tb-width, --tb-height, --tb-ar,
         --tb-inset-top/ right/ bottom/ left (or --tb-inset-x / --tb-inset-y),
         --tb-text-valign:start|center|end -->
    <div class="text-box">
      <img class="text-box__overlay" src="${textBoxOverlay}" alt="" aria-hidden="true">
      <div class="text-content">${text || ''}</div>
    </div>
  </div>
</body>
