}];

// Poll PDFMonkey until image is ready and record workflow-job events.
const createResp = $input.item?.json || {};
const runIx = typeof $runIndex === 'number' ? $runIndex : 0;
const itemIx = $input?.item?.pairedItem?.item ?? (typeof $itemIndex === 'number' ? $itemIndex : 0);

function firstNodeJson(name, itemIndex = itemIx) {
  try {
    const items = $items(name, 0, runIx);
    if (items?.length) {
      return items[itemIndex]?.json || items[0]?.json || {};
    }
  } catch {}
  return {};
}

function parseMaybeJson(value) {
  if (!value || typeof value !== 'string') return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

const orderCtx = {
  ...firstNodeJson('Get Order Ready for Assembly', 0),
  ...firstNodeJson('Generate Page Preview Images'),
};
const doc = createResp.data || createResp.document || createResp;
const docMeta = parseMaybeJson(doc.meta) || (doc.meta && typeof doc.meta === 'object' ? doc.meta : {});
const docPayload = parseMaybeJson(doc.payload) || (doc.payload && typeof doc.payload === 'object' ? doc.payload : {});
const docId = doc.id || doc.document_id || doc.data?.id || null;
const apiBase = 'https://api.pdfmonkey.io/api/v1/documents/';
const statusUrl = docId ? `${apiBase}${docId}` : null;
const http = this.helpers.httpRequest;
const AUTH_HEADER = { Authorization: 'Bearer 2zpxHdmsse2ECXgVVtVR' };
const backendUrl = String(
  orderCtx.backendUrl ||
    createResp.backendUrl ||
    'https://admin.littleherolabs.com',
).replace(/\/$/, '');

const orderId =
  orderCtx.orderId ||
  createResp.orderId ||
  docMeta.orderId ||
  docPayload.order_id ||
  null;
const amazonOrderId =
  orderCtx.amazonOrderId ||
  createResp.amazonOrderId ||
  docMeta.amazonOrderId ||
  docPayload.amazon_order_id ||
  orderId;
const rootOrderId =
  orderCtx.rootOrderId ||
  createResp.rootOrderId ||
  docMeta.rootOrderId ||
  docPayload.root_order_id ||
  amazonOrderId;
const pageNumber = Number.isFinite(Number(orderCtx.pageNumber))
  ? Number(orderCtx.pageNumber)
  : Number.isFinite(Number(createResp.pageNumber))
    ? Number(createResp.pageNumber)
    : Number.isFinite(Number(docPayload.page_number))
      ? Number(docPayload.page_number)
      : null;
const pageImageR2Key =
  orderCtx.pageImageR2Key ||
  createResp.pageImageR2Key ||
  docMeta.pageImageR2Key ||
  docPayload.page_image_r2_key ||
  null;
const workflowJobId =
  typeof orderCtx.workflowJobId === 'number'
    ? orderCtx.workflowJobId
    : typeof createResp.workflowJobId === 'number'
      ? createResp.workflowJobId
      : null;
const workflowJobIdempotencyKey =
  orderCtx.workflowJobIdempotencyKey ||
  createResp.workflowJobIdempotencyKey ||
  null;
const workflowAttemptId =
  typeof orderCtx.workflowAttemptId === 'number'
    ? orderCtx.workflowAttemptId
    : typeof createResp.workflowAttemptId === 'number'
      ? createResp.workflowAttemptId
      : null;

async function logWorkflowEvent(body) {
  if (!workflowJobId && !workflowJobIdempotencyKey) {
    return null;
  }

  return await this.helpers.httpRequest({
    method: 'POST',
    url: backendUrl + '/api/internal/workflow-jobs/log-event',
    headers: {
      Authorization: 'Bearer e41d510ce6ed6e9c7f602fea860f2591cc7ec75fe63e448336a97c4b73898646',
      'Content-Type': 'application/json',
    },
    body,
    json: true,
    timeout: 90000,
  });
}

function buildContext(extra = {}) {
  return {
    ...orderCtx,
    ...createResp,
    orderId,
    amazonOrderId,
    rootOrderId,
    pageNumber,
    pageImageR2Key,
    pdfMonkeyImageDocumentId: docId,
    pdfMonkeyImageStatusUrl: statusUrl,
    ...extra,
  };
}

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || doc.file_url || null;
let attempts = 0;
let submitLog = null;
let lastPollLog = null;

async function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

try {
  if (!docId) {
    throw new Error('PDFMonkey create response missing id');
  }

  submitLog = await logWorkflowEvent({
    jobId: workflowJobId ?? undefined,
    idempotencyKey: workflowJobIdempotencyKey || undefined,
    attemptId: workflowAttemptId ?? null,
    eventType: 'provider-submitted',
    jobStatus: 'polling',
    attemptStatus: 'polling',
    externalProvider: 'pdfmonkey',
    externalRequestId: docId,
    externalStatusUrl: statusUrl,
    payload: {
      orderId,
      pageNumber,
      pageImageR2Key,
      documentKind: 'page-preview',
    },
    context: buildContext({
      pdfMonkeyStatus: status,
      documentKind: 'page-preview',
    }),
  });

  while (attempts < 30) {
    if (status === 'success' && downloadUrl) break;

    const resp = await http({
      method: 'GET',
      url: apiBase + docId,
      json: true,
      headers: AUTH_HEADER,
    });
    const d = resp.data || resp.document || resp;
    status = d.status;
    downloadUrl = d.download_url || d.file_url || null;
    attempts += 1;

    lastPollLog = await logWorkflowEvent({
      jobId: workflowJobId ?? undefined,
      idempotencyKey: workflowJobIdempotencyKey || undefined,
      attemptId: workflowAttemptId ?? null,
      eventType: 'poll-tick',
      jobStatus: 'polling',
      attemptStatus: 'polling',
      externalProvider: 'pdfmonkey',
      externalRequestId: docId,
      externalStatusUrl: statusUrl,
      payload: {
        orderId,
        pageNumber,
        pageImageR2Key,
        documentKind: 'page-preview',
        pollAttempt: attempts,
        pdfMonkeyStatus: status || null,
      },
      context: buildContext({
        pdfMonkeyStatus: status,
        pollAttempt: attempts,
        documentKind: 'page-preview',
      }),
    });

    if (status === 'error' || status === 'failure') {
      throw new Error(`PDFMonkey image polling failed (status=${status})`);
    }

    if (status === 'success' && downloadUrl) break;

    await sleep(1800 + Math.floor(Math.random() * 600));
  }

  if (status !== 'success' || !downloadUrl) {
    throw new Error(`PDFMonkey image not ready after polling (status=${status})`);
  }

  return {
    json: {
      ...buildContext({
        pdfMonkeyStatus: status,
        pdfMonkeyPollAttempts: attempts,
      }),
      pageImageDownloadUrl: downloadUrl,
      workflowLogEvent: {
        submitted: submitLog && typeof submitLog === 'object' ? submitLog : null,
        polled: lastPollLog && typeof lastPollLog === 'object' ? lastPollLog : null,
      },
    },
  };
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);

  try {
    await logWorkflowEvent({
      jobId: workflowJobId ?? undefined,
      idempotencyKey: workflowJobIdempotencyKey || undefined,
      attemptId: workflowAttemptId ?? null,
      eventType: 'provider-failed',
      jobStatus: 'failed',
      attemptStatus: 'failed',
      externalProvider: 'pdfmonkey',
      externalRequestId: docId,
      externalStatusUrl: statusUrl,
      lastError: {
        message,
        orderId,
        pageNumber,
        pageImageR2Key,
        documentKind: 'page-preview',
        pollAttempt: attempts || null,
        pdfMonkeyStatus: status || null,
      },
      payload: {
        orderId,
        pageNumber,
        pageImageR2Key,
        documentKind: 'page-preview',
        pollAttempt: attempts || null,
        pdfMonkeyStatus: status || null,
      },
      context: buildContext({
        errorMessage: message,
        pdfMonkeyStatus: status,
        pollAttempt: attempts,
        documentKind: 'page-preview',
      }),
    });
  } catch (logError) {
    console.warn('Failed to record W3 page workflow job error', logError?.message || logError);
  }

  throw error;
}

