const RUN_BUST = encodeURIComponent(order.runStamp || order.runId || Date.now());
function toAbsoluteAsset(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  return `${backendUrl}/api/assets/${raw.replace(/^\/+/, '')}`;
}
function withBust(value) {
  if (!value) return '';
  const sep = value.includes('?') ? '&' : '?';
  return `${value}${sep}v=${RUN_BUST}`;
}
function norm(value) {
  return withBust(toAbsoluteAsset(value));
}

const firstStr = (...values) => values.find((value) => typeof value === 'string' && value.trim().length) || '';

function deepFindUrl(obj, keyRegex) {
  try {
    const seen = new Set();
    const stack = [obj];
    while (stack.length) {
      const cur = stack.pop();
      if (!cur || typeof cur !== 'object' || seen.has(cur)) continue;
      seen.add(cur);
      for (const [key, value] of Object.entries(cur)) {
        if (keyRegex.test(String(key))) {
          if (typeof value === 'string' && value) return value;
          if (value && typeof value === 'object') {
            const hit = firstStr(value.imagePath, value.url, value.publicUrl, value.href, value.r2Key);
            if (hit) return hit;
          }
        }
        if (value && typeof value === 'object') stack.push(value);
      }
    }
  } catch {}
  return '';
}

const backgrounds = Array.isArray(order.backgroundImages) ? order.backgroundImages : [];
const storyTexts = Array.isArray(order.storyTexts) ? order.storyTexts : [];

