const findStoryText = (page) => {
  const byPage = storyTexts.find((entry) => Number(entry.pageNumber) === Number(page.index));
  if (byPage?.text) return byPage.text;
  const storyPageNumber = Number(page.storyPageNumber);
  const byStoryPage = storyTexts.find((entry) => Number(entry.storyPageNumber) === storyPageNumber);
  return byStoryPage?.text || '';
};

function findOverlayUrl(page) {
  const overlays = order.overlayImages || order.overlays || {};
  const pageNumber = Number(page.index);

  if (Array.isArray(overlays)) {
    const hit = overlays.find((entry) => Number(entry.pageNumber) === pageNumber && (entry.imagePath || entry.url || entry.publicUrl || entry.r2Key));
    if (hit) {
      return withBust(toAbsoluteAsset(firstStr(hit.imagePath, hit.url, hit.publicUrl, hit.r2Key)));
    }
  } else if (overlays && typeof overlays === 'object' && page.overlaySlot) {
    const candidate = overlays[page.overlaySlot] || deepFindUrl(overlays, new RegExp(page.overlaySlot, 'i'));
    if (candidate) {
      return withBust(toAbsoluteAsset(firstStr(candidate.imagePath, candidate.url, candidate.publicUrl, candidate.r2Key, candidate)));
    }
  }

  if (page.overlaySlot === 'animalTracks' && p05OverlayUrlFromCtx) {
    return withBust(p05OverlayUrlFromCtx);
  }

  return null;
}

function findPose(page) {
  if (page.poseNumber === null || page.poseNumber === undefined || page.poseNumber === '') {
    return null;
  }
  const poseNumber = Number(page.poseNumber);
  if (!Number.isFinite(poseNumber)) return null;
  const poses = order.characterImages?.poses || [];
  let pose = poses.find((entry) => Number(entry.poseNumber) === poseNumber);
  if (!pose && Number(page.storyPageNumber) === 14) {
    pose = poses.find((entry) => /fly|flying/i.test(entry.poseFilename || entry.filename || ''));
  }
  if (!pose) return null;
  const imagePath = norm(pose.imagePath || pose.url || pose.publicUrl || pose.href || '');
  return { ...pose, imagePath };
}

const BASE = 2550;
const PX = 2625;
const SCALE = PX / BASE;
const toPx = (value) => `${Math.round(Number(value || 0) * SCALE)}px`;

const CHAR = {
  1: { left: 1453, top: 1938, w: 900 },
  2: { left: 1403, top: 2091, w: 950 },
  3: { left: 1275, top: 1905, w: 900 },
  4: { left: 1020, top: 2100, w: 1100 },
  5: { left: 1250, top: 2066, w: 900 },
  6: { left: 1326, top: 2070, w: 900 },
  7: { left: 1199, top: 1683, w: 900 },
  8: { left: 1595, top: 1920, w: 1100 },
  9: { left: 1352, top: 2066, w: 1100 },
  10: { left: 1275, top: 2295, w: 1300 },
  11: { left: 1964, top: 2117, w: 500 },
  12: { left: 893, top: 2066, w: 920 },
  14: { left: 1225, top: 2040, w: 1500 },
};

const OV3 = { left: 1020, top: 2090, w: 1100 };
const OV4 = { left: 1530, top: 1734, w: 1100 };
const OV14 = { left: 1225, top: 2040, w: 1500 };

function charStyle(storyPageNumber) {
  if (storyPageNumber === 3) {
    return [
