      `top:${toPx(OV3.top)}`,
      'transform:translate(-50%,-100%)',
      `width:${toPx(OV3.w)}`,
      'z-index:11',
    ].join('; ') + ';';
  }

  if (storyPageNumber === 4) {
    return [
      `left:${toPx(OV4.left)}`,
      `top:${toPx(OV4.top)}`,
      'transform:translate(-50%,-100%) rotate(-20deg)',
      `width:${toPx(OV4.w)}`,
      'z-index:11',
    ].join('; ') + ';';
  }

  if (storyPageNumber === 14) {
    return [
      `left:${toPx(OV14.left)}`,
      `top:${toPx(OV14.top)}`,
      'transform:translate(-50%,-100%)',
      `width:${toPx(OV14.w)}`,
      'z-index:11',
    ].join('; ') + ';';
  }

  const character = CHAR[storyPageNumber];
  if (!character) return '';

  return [
    `left:${toPx(character.left)}`,
    `top:${toPx(character.top)}`,
    'transform:translate(-50%,-100%)',
    `width:${toPx(character.w)}`,
    'z-index:11',
  ].join('; ') + ';';
}

function normalizeBreaks(value) {
  return String(value || '')
    .replace(/(?:<\s*br\s*\/?\s*>|&lt;\s*br\s*\/?\s*&gt;)/gi, '\n')
    .replace(/\r\n/g, '\n');
}
function widont(segment) {
  return String(segment).replace(/\s+([^\s]{1,12})$/u, '\u00A0$1');
}
function formatText(raw) {
  return normalizeBreaks(raw).split(/\n/).map((segment) => widont(segment.trim())).join('\n');
}
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (match) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  }[match]));
}

function preloadHTML(urls) {
  const uniqueUrls = Array.from(new Set((urls || []).filter((url) => typeof url === 'string' && url)));
  if (!uniqueUrls.length) return '';
  const imgs = uniqueUrls
    .map((url) => `<img src="${url}" width="1" height="1" alt="" loading="eager" decoding="sync" fetchpriority="high">`)
    .join('');
  return `<div class="__preloads" style="position:absolute;left:-9999px;top:-9999px;width:1px;height:1px;overflow:hidden;opacity:0;visibility:hidden;">${imgs}</div>`;
}

function bgLayerHTML(url) {
  if (!url) return '';
  if (!useImgBackgrounds) {
    return `<div class="page-bg" style="background-image:url('${url}');"></div>`;
  }
  return `<div class="page-bg"><img src="${url}" alt="" loading="eager" decoding="sync" fetchpriority="high" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;"></div>`;
}

function overlayLayerHTML(url) {
  if (!url) return '';
  if (!useImgBackgrounds) {
