  return match ? normalizeId(match[1]) : '';
}

function collectOrderIds(items) {
  const ids = new Set();

  for (const item of items) {
    const data = item?.json || item || {};
    const meta = data.result?.meta || {};
    const candidates = [
      data.orderId,
      meta.orderId,
      data.childOrderId,
      data.amazonOrderId,
      data.rootOrderId,
      data.pageImageR2Key,
      data.r2Key,
      data.manifestKey,
    ];

    for (const candidate of candidates) {
      const id = normalizeId(candidate);
      if (id && !String(candidate).includes('/')) {
        ids.add(id);
      }
    }

    const keyOrderId =
      extractOrderIdFromKey(data.pageImageR2Key) ||
      extractOrderIdFromKey(data.r2Key) ||
      extractOrderIdFromKey(data.manifestKey);
    if (keyOrderId) {
      ids.add(keyOrderId);
    }
  }

  return [...ids];
}

function sortPages(items) {
  return [...items].sort((a, b) => Number(a.pageNumber || 0) - Number(b.pageNumber || 0));
}

