/**
 * Acceptance Tests (3A Phase 5)
 * - Compiles a Markdown report and a machine-readable verdict
 * - Reads manifest from "Build 3A Manifest" and page images from "Collect Page Preview Images"
 */
// Gather upstream artifacts
let manifest = null;
let collector = null;
let qa = null;
try { manifest  = $items('Build 3A Manifest', 0, $runIndex)?.[0]?.json?.manifest || null; } catch {}
try { collector = $items('Collect Page Preview Images', 0, $runIndex)?.[0]?.json || null; } catch {}
try { qa = $items('QA Gate (3A Phase 4)', 0, $runIndex)?.[0]?.json?.qa || null; } catch {}

if (!manifest) throw new Error('Acceptance: manifest not found');

const pages = (manifest.pngGeneration && manifest.pngGeneration.pages) || manifest.pages || {};
const pageKeys = Object.keys(pages || {});

// Derive interior pages p01..pNN dynamically from manifest.pages
const interiorKeys = pageKeys.filter(k => /^p\d{2}$/.test(k));
let maxPageNum = 0;
for (const key of interiorKeys) {
  const n = parseInt(key.slice(1), 10);
  if (Number.isFinite(n) && n > maxPageNum) {
    maxPageNum = n;
  }
}

const expectedInteriorKeys = maxPageNum > 0
  ? Array.from({ length: maxPageNum }, (_, i) => {
      const n = i + 1;
      return n < 10 ? `p0${n}` : `p${n}`;
    })
  : [];

// p00_dedication is required for acceptance (unlike QA, which only warns)
const expectedKeys = ['p00_dedication', ...expectedInteriorKeys];
const missing = expectedKeys.filter(k => !(k in pages));
const coverKey = manifest.pngGeneration?.coverSpreadImage || null;

// Verdict booleans
const sizesOk = manifest.pngGeneration?.sizeInterior?.w === 2625
             && manifest.pngGeneration?.sizeInterior?.h === 2625
             && manifest.pngGeneration?.sizeCover?.w === 5203
             && manifest.pngGeneration?.sizeCover?.h === 2625;

const hasAllPages = missing.length === 0
  && expectedKeys.every(k => {
    const v = pages[k];
    return typeof v === 'string'
      ? !!v
      : !!(v && (v.key || v.path || v.r2Key));
  });

const coverOk = !!coverKey;
const qaPass = !!(qa && qa.pass === true);

const collectedCount = Number(collector?.pagePreviewImages?.length || 0);
let testModePagesFromReady = 0;
try {
  testModePagesFromReady =
    Number($items('Get Order Ready for Assembly', 0, $runIndex)?.[0]?.json?.testModePages || 0) || 0;
} catch {}

// Total expected preview images (dedication + interior pages)
// Standard: 1 + 14 = 15; Amazon: 1 + 16 = 17; etc.
const totalExpectedPages = 1 + expectedInteriorKeys.length;
const expectedCollectorCount =
  testModePagesFromReady > 0 ? testModePagesFromReady : totalExpectedPages;

const matchesCollector =
  hasAllPages && (collectedCount >= expectedCollectorCount);

const verdict = {
  sizesOk,
  hasAllPages,
  coverOk,
  qaPass,
  matchesCollector,
  readyToUploadManifest: sizesOk && hasAllPages && coverOk && qaPass
};

// Markdown report
function badge(ok){ return ok ? '✅' : '❌'; }
const lines = [];
lines.push(`# Workflow 3A — Acceptance Report`);
lines.push(`Generated: ${new Date().toISOString()}`);
lines.push('');
lines.push(`**Order:** ${manifest.amazonOrderId || 'UNKNOWN'}  `);
lines.push(`**Character Hash:** ${manifest.characterHash || 'UNKNOWN'}  `);
lines.push('');
lines.push(`## Summary`);
lines.push(`- Sizes: ${badge(verdict.sizesOk)} interior 2625×2625; cover 5203×2625`);
lines.push(`- Pages present: ${badge(verdict.hasAllPages)} (expected ${totalExpectedPages} incl. dedication)`);
lines.push(`- Cover image present: ${badge(verdict.coverOk)}`);
lines.push(`- QA Gate: ${badge(verdict.qaPass)}`);
lines.push(`- Collector consistency: ${badge(verdict.matchesCollector)} (pages=${collectedCount}, expected>=${expectedCollectorCount})`);
lines.push('');
if (missing.length) {
  lines.push(`**Missing pages:** ${missing.join(', ')}`);
  lines.push('');
}
lines.push('## Assets Used');
