// Generate page preview image work items for PDFMonkey.
// Preview-image keys now follow the resolved per-book order root.
function get(obj, path, dflt = null) {
  try {
    return path.split('.').reduce((acc, key) => (acc && acc[key] !== undefined ? acc[key] : undefined), obj) ?? dflt;
  } catch {
    return dflt;
  }
}

const input = $input.first()?.json || {};
const order = input || {};
const orderId = order.orderId || order.amazonOrderId || 'ORDER';
const amazonOrderId = order.amazonOrderId || null;
const rootOrderId = order.rootOrderId || amazonOrderId || orderId;
const bookId = order.bookId || get($items('Extract Manifest URL (3)', 0, $runIndex), '0.json.bookId', 'book-mvp-simple-adventure');
const orderR2BaseKey = order.orderR2BaseKey || `${bookId}/orders/${orderId}`;
const page_css = String(order.page_css || '');
const useImgBackgrounds = order.useImgBackgrounds === false ? false : Boolean(order.useImgBackgrounds ?? true);
const PNG_TEMPLATE_ID = order.pdfMonkeyImageTemplateId || order.pdfMonkeyTemplateId || '23277725-4AB0-446A-98C5-CB99C21822B3';
const backendUrl = order.backendUrl || get($items('Extract Manifest URL (3)', 0, $runIndex), '0.json.backendUrl', 'https://admin.littleherolabs.com');

function extractFragmentsFromPagesHtml(src) {
  const html = String(src || '');
  const re = /<div\s+class=(['"])book-page\1[^>]*>[\s\S]*?<\/div>/gi;
  const out = [];
  let match;
  while ((match = re.exec(html)) !== null) out.push(match[0]);
  return out.length ? out : (html.trim() ? [html] : []);
}

function getPageNumberFromFragment(frag, fallback) {
  const match = /id=(['"])page-(\d+)\1/i.exec(String(frag || ''));
  return match ? Number(match[2]) : Number(fallback);
}

let pages = [];
if (Array.isArray(order.interiorPagesHTML) && order.interiorPagesHTML.length) {
  pages = order.interiorPagesHTML.slice();
} else if (typeof order.pages_html === 'string' && order.pages_html.trim()) {
  pages = extractFragmentsFromPagesHtml(order.pages_html);
} else {
  throw new Error('interiorPagesHTML[] or pages_html is required for generating preview images');
}

if (!Array.isArray(order.interiorPagesHTML) && typeof order.pages_html === 'string') {
  pages = pages.map((frag, idx) => ({ frag, n: getPageNumberFromFragment(frag, idx) }))
    .sort((left, right) => left.n - right.n)
    .map((item) => item.frag);
}

const allItems = [];
for (let index = 0; index < pages.length; index++) {
  const frag = String(pages[index] || '');
  const pageNumber = getPageNumberFromFragment(frag, index);
  const stem = `p${String(pageNumber).padStart(2, '0')}`;
  const filename = `${stem}.png`;
  const r2Key = `${orderR2BaseKey}/preview-images/${filename}`;

  allItems.push({
    json: {
      orderId,
      amazonOrderId,
      rootOrderId,
      bookId,
      orderR2BaseKey,
      backendUrl,
      pageIndex: index,
      pageNumber,
      pageLabel: stem,
      pageHtml: frag,
      pageImageFilename: filename,
      pageImageR2Key: r2Key,
      page_css,
      useImgBackgrounds,
      pdfMonkeyImageTemplateId: PNG_TEMPLATE_ID,
      pdfMonkeyTemplateId: PNG_TEMPLATE_ID,
      workflowJobId: order.workflowJobId ?? null,
      workflowJobIdempotencyKey: order.workflowJobIdempotencyKey || null,
      workflowJobStatus: order.workflowJobStatus || null,
      workflowAttemptId: order.workflowAttemptId ?? null,
      workflowAttempt: order.workflowAttempt ?? null,
      workflowClaimed: order.workflowClaimed === true,
    },
  });
}

let testMode = get($items('Get Order Ready for Assembly', 0, $runIndex), '0.json.testModePages', null);
if (testMode == null) testMode = order.testModePages ?? null;

let result = allItems;
if (Array.isArray(testMode) && testMode.length) {
  const set = new Set(testMode.map((value) => Number(value)));
  result = allItems.filter((item) => set.has(Number(item.json.pageNumber)));
} else if (Number.isFinite(Number(testMode)) && Number(testMode) > 0) {
  const sorted = [...allItems].sort((left, right) => Number(left.json.pageNumber) - Number(right.json.pageNumber));
  result = sorted.slice(0, Number(testMode));
}

return result;

// Idempotency Check - Prevent Duplicate Executions
// Checks if this orderId was recently processed (within last 30 seconds)
// Uses workflow static data to track recent executions

const input = $input.first().json || {};
const orderId = input.orderId || input.amazonOrderId || null;

if (!orderId) {
  // If no orderId, we can't check for duplicates, but we should still proceed
  // (might be a test run or edge case)
  console.warn('⚠️ No orderId found for idempotency check - proceeding anyway');
  return [{ json: input }];
}

const staticData = this.getWorkflowStaticData('global');
const recentExecutions = staticData.recentExecutions || {};
const now = Date.now();
const thirtySecondsAgo = now - 30000;

// Check if this order was recently executed
if (recentExecutions[orderId] && recentExecutions[orderId] > thirtySecondsAgo) {
  const secondsAgo = Math.round((now - recentExecutions[orderId]) / 1000);
  console.log(`⚠️ Duplicate execution detected for orderId: ${orderId} (executed ${secondsAgo}s ago) - skipping`);
  return []; // Empty output stops execution
}

// Record this execution
recentExecutions[orderId] = now;

// Clean up old entries (older than 5 minutes)
const fiveMinutesAgo = now - 300000;
Object.keys(recentExecutions).forEach(key => {
  if (recentExecutions[key] < fiveMinutesAgo) {
    delete recentExecutions[key];
  }
});

staticData.recentExecutions = recentExecutions;

console.log(`✅ Idempotency check passed for orderId: ${orderId}`);

// Pass through original input
return [{ json: input }];

const order = $input.first().json || {};
const pagesGenerated = Array.isArray(order.pagePreviewImages)
  ? order.pagePreviewImages.length
  : Number(order.pagesGenerated || order.totalPages || 0) || 0;

const logEntry = {
  timestamp: new Date().toISOString(),
  workflow: '3-book-assembly-voice-of-wonder',
  orderId:
    order.orderId ||
    order.order_id ||
    order.amazonOrderId ||
    order.amazon_order_id ||
    order.rootOrderId ||
    order.root_order_id ||
    null,
  status: order.status,
  pagesGenerated,
  totalPagesRequired: Number(order.totalPagesRequired || order.total_pages_required || 0) || null,
  assemblyProgress:
    order.assemblyProgress ??
    order.assembly_progress ??
    null,
  finalBookUrl: order.finalBookUrl || order.final_book_url || 'N/A'
};

console.log('Book Assembly Results:', JSON.stringify(logEntry, null, 2));
return [{ json: logEntry }];

function safeNodeFirst(name) {
  try {
    return $items(name, 0, $runIndex)?.[0]?.json || {};
  } catch {
    return {};
  }
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed && trimmed !== 'null' && trimmed !== 'undefined') {
        return trimmed;
      }
      continue;
    }

    if (value !== undefined && value !== null) {
      return value;
    }
  }

