}

const current = $input.first().json || {};
const collected = safeNodeFirst('Collect Page Preview Images');
const ready = safeNodeFirst('Get Order Ready for Assembly');
const prep = safeNodeFirst('Prep Manifest Upload (3)');

const orderId = firstNonEmpty(
